			                var scoreSum13 = ValueUtil.fixNumber(0); //13.문제유형-성
			                var scoreSum14 = ValueUtil.fixNumber(0); //14.문제유형-정신건강
			                var scoreSum15 = ValueUtil.fixNumber(0); //15.문제유형-학교
			                var scoreSum16 = ValueUtil.fixNumber(0); //16.문제유형-사이버
			                var scoreSum2 = ValueUtil.fixNumber(0); //2.정신건강- 자살, 자해제외
			                var scoreSum3 = ValueUtil.fixNumber(0); //3.문제유형-정신건강(자살,자해 )
			                var scoreSum4 = ValueUtil.fixNumber(0); //4.위험요인

			                for (var i = 0; i <voReturnVal.dsList.getRowCount(); i++) {
			                    if (i == 1 || i == 11 ) continue;

			                    var rspnsValue = voReturnVal.dsList.getValue(i, "QESITM_SINGL_RSPNS_VALUE");

			                    if (rspnsValue != "1") rspnsValue = "0";

			                    if (i < 5) { //긴급지원 (0 ~ 4) 1번제외
			                        scoreSum0 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 5 && i < 10) { //문제유형, 가정 1
			                        scoreSum1 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum11 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 10 && i < 16) { //문제유형, 비행  2
			                        scoreSum1 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum12 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 16 && i < 21) { //문제유형, 성3
			                        scoreSum1 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum13 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 21 && i < 31) { //정신건강- 자살, 자해제외
			                        scoreSum2 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum14 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 31 && i < 33) { //문제유형-정신건강(자살,자해 )
			                        scoreSum1 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum3 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum14 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 33 && i < 39) { //문제유형, 학교  5
			                        scoreSum1 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum15 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 39 && i < 43) { //문제유형, 사이버  6
			                        scoreSum1 += ValueUtil.fixNumber(rspnsValue);
			                        scoreSum16 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                    if (i >= 43 && i < 50) { //위기요인
			                        scoreSum3 += ValueUtil.fixNumber(rspnsValue);
			                    }

			                }

			                var crisisScrennResult = "";
			                if (scoreSum0 >= 1) {              //긴급지원 -> 1점이상 진급지원
			                    crisisScrennResult = "1";
			                } else if (scoreSum1 >= 1) {       //문제유형 -> 1점이상 고위험군
			                    crisisScrennResult = "2";
			                } else if (scoreSum2 >= 3) {       //정신건강 3점이상 고위험군
			                    crisisScrennResult = "2";
			                } else if (scoreSum3 >= 1) {      //자살자해 1점이상 -> 고위험군
			                    crisisScrennResult = "2";
			                } else {
			                    crisisScrennResult = "3";
			                }

			                var dsList = app.lookup("dsList");

			                dsList.setValue(0, "CRISIS_SCRENN_EVL_SCORE", scoreSum0);  //진급지원
			                dsList.setValue(1, "CRISIS_SCRENN_EVL_SCORE", scoreSum11); //가정
			                dsList.setValue(2, "CRISIS_SCRENN_EVL_SCORE", scoreSum12); //비행
			                dsList.setValue(3, "CRISIS_SCRENN_EVL_SCORE", scoreSum13); //성
			                dsList.setValue(4, "CRISIS_SCRENN_EVL_SCORE", scoreSum14); //정신건강
			                dsList.setValue(5, "CRISIS_SCRENN_EVL_SCORE", scoreSum15); //학교
			                dsList.setValue(6, "CRISIS_SCRENN_EVL_SCORE", scoreSum16); //사이버
			                dsList.setValue(7, "CRISIS_SCRENN_EVL_SCORE", scoreSum4);  //위험요인
			                dsList.setValue(8, "CRISIS_SCRENN_EVL_SCORE", "");
			                dsList.setValue(9, "CRISIS_SCRENN_RESULT_SE_CD", crisisScrennResult);

